from ta_emss import ta_emss


class ScfcValueTranslator(object):
    def __init__(self, emss_host, emss_port):
        self.ute_emss = ta_emss("Translator", host=emss_host, port=emss_port)

    def translate(self, data):
        for managed_object in data:
            class_name = managed_object.label._class
            for attribute in managed_object.attributes:
                attribute_name = attribute.get_name()
                if attribute.is_scalar():
                    attribute.set_emss_value(self.ask_ute_emss_for_value(class_name, attribute_name, attribute.value))
                else:
                    if attribute.value == []:
                        attribute.set_emss_value("")
                    elif not attribute.has_subattributes():
                        attribute.set_emss_value([self.ask_ute_emss_for_value(class_name, attribute_name, record) for record in attribute.value])
                    else:
                        attribute.set_emss_value([{subattribute_name: self.ask_ute_emss_for_value(class_name,
                                                                                                  "%s.%s" % (attribute_name, subattribute_name),
                                                                                                  subattribute_value) for
                                                   subattribute_name, subattribute_value in record.items()} for record in attribute.value])

    def ask_ute_emss_for_value(self, class_name, attribute_name, value):
        return self.ute_emss.translate_scfc_value_to_user_interface_format(class_name, attribute_name, '"%s"' % value)
